  'help.type.other': 'Outro',
  'help.faq.cantLogin.q': 'Não consigo acessar a minha conta',
  'help.faq.cantLogin.a': 'Verifica se estás a usar o email e a palavra-passe corretos. Se esqueceste a palavra-passe, clica em "Esqueceu a palavra-passe?" na tela de login. Se o problema persistir, cria um ticket de suporte.',
  'help.faq.notReceiving.q': 'Não estou a receber emails',
  'help.faq.notReceiving.a': 'Verifica a pasta de Spam primeiro. Certifica-te que o teu armazenamento não está cheio. Se o problema continuar, confirma que o remetente tem o endereço correto e cria um ticket.',
  'help.faq.cantSend.q': 'Não consigo enviar emails',
  'help.faq.cantSend.a': 'Verifica a tua conexão com a internet e se o endereço do destinatário está correto. Confirma se os anexos não ultrapassam 25MB. Tenta novamente em alguns minutos.',
  'help.faq.forgotPassword.q': 'Esqueci a minha palavra-passe',
  'help.faq.forgotPassword.a': 'Na tela de login, clica em "Esqueceu a palavra-passe?" e segue as instruções para redefinir a tua palavra-passe pelo email de recuperação.',
  'help.faq.accountSecurity.q': 'Acho que a minha conta foi comprometida',
  'help.faq.accountSecurity.a': 'Altera a tua palavra-passe imediatamente. Verifica a pasta Enviados por mensagens que não enviaste. Ativa a autenticação em duas etapas em Configurações > Segurança. Se necessário, cria um ticket urgente.',
  'help.faq.appAccess.q': 'Como acedo ao app no telemóvel?',
  'help.faq.appAccess.a': 'Podes aceder ao Chatyy pelo navegador em chatyy.com, ou baixar o nosso app na loja de aplicações do teu dispositivo.',
  'privacy.title': 'Política de Privacidade',
  'privacy.subtitle': 'Como protegemos e tratamos os teus dados',
  'privacy.lastUpdated': 'Última atualização: Março 2026',
  'privacy.dataCollection.title': 'Coleta de Dados',
  'privacy.dataCollection.body': 'Coletamos apenas as informações necessárias para o serviço de email: o teu nome, endereço de email e o conteúdo das mensagens enviadas e recebidas. Não vendemos nem partilhamos os teus dados pessoais com terceiros para fins de marketing.',
  'privacy.dataUsage.title': 'Como Usamos os Teus Dados',
  'privacy.dataUsage.body': 'Os teus dados são usados exclusivamente para operar e melhorar o serviço de email, incluindo entrega de mensagens, filtragem de spam, recursos de IA (com o teu consentimento) e segurança da conta.',
  'privacy.dataSecurity.title': 'Segurança dos Dados',
  'privacy.dataSecurity.body': 'Usamos criptografia padrão da indústria (TLS/SSL) para todos os dados em trânsito e em repouso. Sessões são protegidas com tokens criptografados e proteção CSRF. Auditamos regularmente as nossas práticas de segurança.',
  'privacy.cookies.title': 'Cookies e Armazenamento Local',
  'privacy.cookies.body': 'Usamos cookies essenciais e armazenamento local para manter a tua sessão, lembrar as tuas preferências (tema, idioma) e proporcionar uma experiência fluida. Não usamos cookies de rastreamento de terceiros.',
  'privacy.thirdParties.title': 'Serviços de Terceiros',
  'privacy.thirdParties.body': 'Podemos usar serviços de terceiros para funcionalidades específicas como IA (Anthropic Claude) e notificações push. Esses serviços seguem as suas próprias políticas de privacidade e processam apenas o mínimo de dados necessário.',
  'privacy.rights.title': 'Os Teus Direitos',
  'privacy.rights.body': 'Tens o direito de aceder, corrigir, exportar ou eliminar os teus dados pessoais a qualquer momento. Podes gerir os teus dados em Configurações ou contactando o nosso suporte.',
  'privacy.contact.title': 'Fala Connosco',
  'privacy.contact.body': 'Para questões de privacidade ou solicitações de dados, entra em contacto pelo privacy@chatyy.com. Responderemos em até 30 dias.',
  'terms.title': 'Termos de Serviço',
  'terms.subtitle': 'Diretrizes de uso do Chatyy',
  'terms.lastUpdated': 'Última atualização: Março 2026',
  'terms.acceptance.title': 'Aceitação dos Termos',
  'terms.acceptance.body': 'Ao aceder ou usar o Chatyy, concordas com estes Termos de Serviço. Se não concordares com qualquer parte destes termos, não utilizes o serviço.',
  'terms.services.title': 'Descrição dos Serviços',
  'terms.services.body': 'O Chatyy fornece serviços de comunicação por email incluindo envio, recebimento e gestão de emails, além de recursos de IA, integração com calendário e videoconferência.',
  'terms.accounts.title': 'Contas de Utilizador',
  'terms.accounts.body': 'Tu és responsável por manter a segurança das tuas credenciais. Não partilhes a tua palavra-passe nem permitas acesso não autorizado à tua conta. Deves ter pelo menos 13 anos para usar este serviço.',
  'terms.conduct.title': 'Uso Aceitável',
  'terms.conduct.body': 'Concordas em não usar o serviço para enviar spam, malware, phishing ou qualquer conteúdo ilegal. Não tentes aceder a contas de outros utilizadores ou interromper a infraestrutura do serviço.',
  'terms.content.title': 'Propriedade do Conteúdo',
  'terms.content.body': 'Manténs a propriedade de todo o conteúdo que crias e envias pelo serviço. Não reivindicamos propriedade sobre os teus emails ou anexos. Podemos processar o conteúdo conforme necessário para fornecer o serviço.',
  'terms.limitation.title': 'Limitação de Responsabilidade',
  'terms.limitation.body': 'O Chatyy é fornecido "como está". Buscamos 99,9% de disponibilidade mas não garantimos serviço ininterrupto. Não somos responsáveis por danos indiretos, incidentais ou consequentes decorrentes do uso do serviço.',
  'terms.termination.title': 'Encerramento de Conta',
  'terms.termination.body': 'Podemos suspender ou encerrar contas que violem estes termos. Podes eliminar a tua conta a qualquer momento em Configurações. Após o encerramento, os teus dados serão eliminados em até 30 dias.',
  'terms.changes.title': 'Alterações aos Termos',
  'terms.changes.body': 'Podemos atualizar estes termos periodicamente. Notificaremos sobre alterações significativas por email ou notificação no app. O uso continuado após as alterações constitui aceitação dos termos atualizados.',
