  'plans.faqWhatIsPlus': 'O que é o Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'É o plano premium do Chatyy que protege todas as tuas conversas, fotos e vídeos. Com o Chatyy One, mesmo que apagues algo sem querer, podes recuperar em até 30 dias. Além disso, ganhas 200GB de armazenamento, One AI como assistente pessoal, e podes enviar ficheiros de até 100MB.',
  'plans.faqCancelAnswer': 'O teu plano continua ativo até ao final do período pago. Depois disso, voltas para o plano gratuito. As tuas fotos e vídeos que excederem 15GB serão mantidos por mais 30 dias para fazeres download.',
  'plans.faqHowFamily': 'Como funciona o plano Pro?',
  'plans.faqHowFamilyAnswer': 'Podes adicionar até 4 pessoas da tua família. Todos partilham 500GB de armazenamento e recebem todos os benefícios do Chatyy One. Cada pessoa tem o seu espaço privado — ninguém vê os ficheiros dos outros.',
  'plans.faqChangePlanAnswer': 'Sim! Se fizeres upgrade do Plus para Pro, só será cobrada a diferença proporcional. Se fizeres downgrade, o plano atual continua até ao final do período.',
  'plans.faqCardDeclined': 'O meu cartão foi recusado, o que faço?',
  'plans.faqCardDeclinedAnswer': 'Tens 7 dias para atualizar o teu cartão. Durante esse período, todos os teus benefícios continuam a funcionar. Depois de 7 dias, o plano volta para o gratuito.',
  'plans.faqDataSafe': 'Os meus dados estão seguros?',
  'plans.faqDataSafeAnswer': 'Sim! Os teus dados de pagamento são processados com criptografia de ponta a ponta. Não armazenamos o número do teu cartão — apenas os últimos 4 dígitos para a tua referência.',
